insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion under careful supervision, as described in a classroom discussion in a southern research briefing context.','The researchers made a recommendation because the data were complete.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','The researchers postponed collecting data after reaching a firm conclusion.','The available data forced the researchers to reject all conclusions.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_49", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes after initial trials, as described in a research summary in a central research briefing context.','The author believes mistakes should be ignored during practice.','The author claims feedback is useful only when students stop practicing.','The author believes practice works best if learners are told what they did wrong.','The author suggests that practice and feedback are unrelated.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_49", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The new system was adopted not because it was cheaper, but because it made the process more transparent in schools, as described in a public debate in a online research briefing context.','The new system was adopted mainly because it reduced costs.','The new system was rejected because it was not transparent.','The process became less transparent after the new system was adopted.','The main reason for adopting the new system was improved transparency rather than lower cost.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_49", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Even though the experiment was small, its results raised important questions for future research for adult learners, as described in a training program in a evening research briefing context.','Despite its limited size, the experiment produced results that future studies should examine.','Future research became unnecessary after the experiment.','The experiment was too large to raise useful questions.','The results were ignored because the experiment was not small.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_49", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The passage implies that convenience may encourage people to use a service, but it does not guarantee satisfaction in public institutions, as described in an evaluation report in a summer research briefing context.','The passage denies that convenience affects service use.','The passage suggests that a convenient service can attract users without necessarily satisfying them.','The passage argues that inconvenient services attract the most users.','The passage says convenience always guarantees satisfaction.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_49", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
