insert into passages (title,body,"wordCount",difficulty,topic,status) values ('Cities and Quiet Spaces', 'Modern cities are often described in terms of movement, traffic, and noise. Yet many residents depend on quiet public spaces to read, think, or recover from a demanding day. Parks, libraries, and pedestrian streets can improve urban life not by increasing activity, but by offering a pause from it. This is why planners increasingly view silence and rest as resources rather than luxuries. The discussion is framed around a realistic situation in which readers must distinguish the central claim from tempting but exaggerated conclusions.', 84, 6, 'urban quiet', 'approved');
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',6,'What can be inferred from the passage?','A careful approach is better than an automatic or extreme response.','The author rejects all practical solutions.','The passage supports ignoring evidence.','The author believes simple choices are always wrong.','A','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_1", "reading_comprehension", "practice_pool"]'::jsonb,80,'B2',(select max(id) from passages),'approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',6,'Which of the following would best support the passage’s argument?','An example unrelated to the topic.','An example showing that thoughtful use leads to better results than careless use.','A claim that all methods work equally well.','A story showing that evidence is never useful.','B','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_1", "reading_comprehension", "practice_pool"]'::jsonb,80,'C1',(select max(id) from passages),'approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',6,'The word “rather” in the passage is used to','mark the end of the discussion.','repeat the previous idea without change.','introduce a more accurate interpretation.','give an unrelated example.','C','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_1", "reading_comprehension", "practice_pool"]'::jsonb,80,'B2',(select max(id) from passages),'approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',6,'Why does the author mention examples in the passage?','To distract readers from the main idea.','To prove that examples are always unreliable.','To show that the topic belongs only to the past.','To make the general claim more concrete.','D','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_1", "reading_comprehension", "practice_pool"]'::jsonb,80,'C1',(select max(id) from passages),'approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',6,'Which conclusion is most consistent with the passage?','The topic should be used with judgment rather than accepted blindly.','The topic has no practical consequences.','The topic should be banned in all cases.','The passage offers no conclusion at all.','A','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_1", "reading_comprehension", "practice_pool"]'::jsonb,80,'B2',(select max(id) from passages),'approved',false);
insert into passages (title,body,"wordCount",difficulty,topic,status) values ('Feedback in Learning', 'Feedback is useful only when learners understand how to act on it. A comment such as “improve your writing” may be accurate, but it gives little direction. More effective feedback identifies a specific weakness and suggests a next step. This helps learners focus their effort and reduces frustration. In this sense, feedback is not simply evaluation; it is guidance for future performance. The discussion is framed around a realistic situation in which readers must distinguish the central claim from tempting but exaggerated conclusions.', 83, 6, 'feedback', 'approved');
